// เซนเซอร์ที่ 01 : เซนเซอร์วัดชีพจร (Heartbeat / Pulse Sensor)
// ฐานที่ 1  ·  บอร์ด Arduino Uno R3
// การต่อสาย : VCC->5V , GND->GND , S/OUT->A0

const int PIN_PULSE = A0;
int threshold = 550;              // ค่าเกณฑ์ ปรับตามเซนเซอร์
unsigned long lastBeat = 0;
int bpm = 0;

void setup() {
  Serial.begin(9600);
}

void loop() {
  int value = analogRead(PIN_PULSE);
  if (value > threshold && millis() - lastBeat > 300) {
    bpm = 60000 / (millis() - lastBeat);
    lastBeat = millis();
    Serial.print("BPM = ");
    Serial.println(bpm);
  }
  delay(10);
}

fun.code:
// ============================================================
// ฐาน 1 · เซนเซอร์ 01 · เซนเซอร์วัดชีพจร
// ลูกเล่น : บัซเซอร์เต้นตามหัวใจ + LED กระพริบทุกครั้งที่หัวใจเต้น
// ต่อสาย  : เซนเซอร์ S->A0, VCC->5V, GND->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int PIN_PULSE = A0;
const int BUZZER    = 8;
const int LED       = 13;

float ema = 0;          // ค่าที่กรองความสั่นออกแล้ว
float baseline = 0;     // เส้นฐาน ปรับตามตัวเองอัตโนมัติ
bool  beating = false;
unsigned long lastBeat = 0;
int bpm = 0;

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  ema = baseline = analogRead(PIN_PULSE);
  Serial.println("วางนิ้วแล้วนิ่ง ๆ 5 วินาที");
}

void loop() {
  int raw = analogRead(PIN_PULSE);
  ema      = 0.75 * ema      + 0.25 * raw;    // กรองสัญญาณรบกวน
  baseline = 0.98 * baseline + 0.02 * ema;    // เส้นฐานไหลตามช้า ๆ

  float threshold = baseline + 6;             // สูงกว่าเส้นฐานเท่านี้ = หัวใจเต้น

  if (!beating && ema > threshold && millis() - lastBeat > 300) {
    beating = true;
    unsigned long gap = millis() - lastBeat;
    lastBeat = millis();

    if (gap < 2000) {                         // คิด BPM เฉพาะจังหวะที่สมเหตุผล
      bpm = 60000 / gap;
      if (bpm >= 40 && bpm <= 200) {
        Serial.print("ตุ้บ!  BPM = ");
        Serial.println(bpm);
      }
    }
    digitalWrite(LED, HIGH);
    beep(880, 40);                            // เสียงตุ้บสั้น ๆ ตามหัวใจ
    digitalWrite(LED, LOW);
  }
  if (beating && ema < baseline + 2) beating = false;

  delay(10);
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

