// ============================================================
// ฐาน 1 · เซนเซอร์ 01 · ชีพจร  [ลูกเล่น + LCD]
// LCD โชว์ BPM ตัวใหญ่ + บัซเซอร์เต้นตามหัวใจ
// ต่อสาย : เซนเซอร์ S->A0 | บัซเซอร์ +->D8 | LCD SDA->A4, SCL->A5, VCC->5V, GND->GND
// ต้องลงไลบรารี LiquidCrystal I2C ของ Frank de Brabander
// ============================================================
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);      // ถ้าจอไม่ติด ลองเปลี่ยนเป็น 0x3F

const int PIN_PULSE = A0;
const int BUZZER = 8;

float ema = 0, baseline = 0;
bool  beating = false;
unsigned long lastBeat = 0;
int bpm = 0;

void setup() {
  pinMode(BUZZER, OUTPUT);
  lcd.init();
  lcd.backlight();
  lcd.print("Pulse Sensor");
  lcd.setCursor(0, 1);
  lcd.print("Place finger");
  ema = baseline = analogRead(PIN_PULSE);
  delay(1500);
  lcd.clear();
}

void loop() {
  int raw = analogRead(PIN_PULSE);
  ema      = 0.75 * ema      + 0.25 * raw;
  baseline = 0.98 * baseline + 0.02 * ema;

  if (!beating && ema > baseline + 6 && millis() - lastBeat > 300) {
    beating = true;
    unsigned long gap = millis() - lastBeat;
    lastBeat = millis();

    if (gap < 2000) {
      int v = 60000 / gap;
      if (v >= 40 && v <= 200) { bpm = v; showBpm(); }
    }
    tone(BUZZER, 880, 40);                // เสียงตุ้บตามหัวใจ
  }
  if (beating && ema < baseline + 2) beating = false;

  delay(10);
}

void showBpm() {
  lcd.setCursor(0, 0);
  lcd.print("BPM = ");
  lcd.print(bpm);
  lcd.print("   ");

  lcd.setCursor(0, 1);                    // แถบหัวใจตามความเร็ว
  int bars = map(bpm, 50, 150, 1, 16);
  bars = constrain(bars, 1, 16);
  for (int i = 0; i < 16; i++) lcd.print(i < bars ? '#' : ' ');
}

