// เซนเซอร์ที่ 02 : เซนเซอร์ฝุ่น PM2.5
// ฐานที่ 1  ·  บอร์ด Arduino Uno R3
// การต่อสาย : VCC->5V , GND->GND , TX->D10 , RX->D11

#include <SoftwareSerial.h>
SoftwareSerial pms(10, 11);       // RX, TX
byte buf[32];

void setup() {
  Serial.begin(9600);
  pms.begin(9600);
}

void loop() {
  if (pms.available() >= 32) {
    pms.readBytes(buf, 32);
    if (buf[0] == 0x42 && buf[1] == 0x4D) {      // ตรวจหัวข้อมูล
      int pm25 = buf[12] * 256 + buf[13];
      Serial.print("PM2.5 = ");
      Serial.print(pm25);
      Serial.println(" ug/m3");
    }
  }
}

// เซนเซอร์ที่ 03 : เซนเซอร์อุณหภูมิและความชื้น
// ฐานที่ 2  ·  บอร์ด Arduino Uno R3
// การต่อสาย : VCC->5V , GND->GND , DATA->D2
// ต้องติดตั้งไลบรารี "DHT sensor library" ของ Adafruit ก่อน

#include <DHT.h>
#define DHTPIN  2
#define DHTTYPE DHT11            // ชนิดของโมดูลที่ใช้จริง
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  Serial.print("Temp = ");
  Serial.print(t);
  Serial.print(" C   Humi = ");
  Serial.print(h);
  Serial.println(" %");
  delay(2000);
}

