// ============================================================
// ฐาน 2 · เซนเซอร์ 03 · เซนเซอร์อุณหภูมิและความชื้น
// ลูกเล่น : ร้อนเกินกำหนด บัซเซอร์เตือน + LED ติด (เครื่องเฝ้าโรงเรือน)
// ต่อสาย  : DHT out->D2, +->5V, -->GND | บัซเซอร์ +->D8, -->GND
// ต้องลงไลบรารี DHT sensor library ของ Adafruit
// ============================================================
#include <DHT.h>
#define DHTPIN  2
#define DHTTYPE DHT11          // ของจริงเป็น DHT11
DHT dht(DHTPIN, DHTTYPE);

const int BUZZER = 8;
const int LED    = 13;

float limitTemp = 32.0;        // เกิน 32 องศาถือว่าร้อนเกินไป

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  dht.begin();
}

void loop() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();

  if (isnan(t) || isnan(h)) {           // อ่านไม่ได้ ให้ข้ามรอบนี้
    Serial.println("อ่านค่าไม่ได้ ตรวจสายอีกครั้ง");
    delay(2000);
    return;
  }

  Serial.print("อุณหภูมิ ");  Serial.print(t);
  Serial.print(" C   ความชื้น "); Serial.print(h); Serial.print(" %");

  if (t > limitTemp) {
    Serial.println("   >> ร้อนเกินไป!");
    digitalWrite(LED, HIGH);
    for (int i = 0; i < 3; i++) { beep(2000, 100); delay(100); }
  } else {
    Serial.println("   ปกติ");
    digitalWrite(LED, LOW);
  }
  delay(2000);
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

