// เซนเซอร์ที่ 04 : เซนเซอร์แสง (Photoresistor / LDR)
// ฐานที่ 2  ·  บอร์ด Arduino Uno R3
// การต่อสาย : VCC->5V , GND->GND , AO->A0

const int PIN_LDR = A0;
const int PIN_LED = 13;

void setup() {
  Serial.begin(9600);
  pinMode(PIN_LED, OUTPUT);
}

void loop() {
  int light = analogRead(PIN_LDR);
  Serial.print("Light = ");
  Serial.println(light);

  if (light < 300) {                        // มืด
    digitalWrite(PIN_LED, HIGH);            // เปิดไฟ
  } else {
    digitalWrite(PIN_LED, LOW);
  }
  delay(200);
}

