// เซนเซอร์ที่ 05 : รีเลย์ (Relay Module 1 ช่อง 5V)
// ฐานที่ 3  ·  บอร์ด Arduino Uno R3
// การต่อสาย : VCC->5V , GND->GND , IN->D8 , COM/NO->โหลด
// ห้ามต่อไฟบ้าน 220V ในกิจกรรมนี้เด็ดขาด

const int PIN_RELAY = 8;

void setup() {
  pinMode(PIN_RELAY, OUTPUT);
  digitalWrite(PIN_RELAY, HIGH);   // HIGH = ปิด (โมดูล active LOW)
}

void loop() {
  digitalWrite(PIN_RELAY, LOW);    // เปิดอุปกรณ์
  delay(3000);

  digitalWrite(PIN_RELAY, HIGH);   // ปิดอุปกรณ์
  delay(3000);
}

fun.code:
// ============================================================
// ฐาน 3 · เซนเซอร์ 05 · รีเลย์
// ลูกเล่น : กดปุ่มเปิดปิดอุปกรณ์ + จับเวลาว่าเปิดมากี่วินาที
// ต่อสาย  : รีเลย์ IN->D8 | ปุ่มกด ขาหนึ่ง->D2 อีกขา->GND
//           บัซเซอร์ +->D9, -->GND   (รีเลย์ใช้ D8 อยู่ บัซเซอร์จึงย้ายมา D9)
// ============================================================
const int RELAY  = 8;
const int BUTTON = 2;
const int BUZZER = 9;
const int LED    = 13;

bool relayOn   = false;
bool lastState = HIGH;
unsigned long onSince = 0;

void setup() {
  Serial.begin(9600);
  pinMode(RELAY, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  digitalWrite(RELAY, HIGH);              // HIGH = ปิด (โมดูล active LOW)
  Serial.println("กดปุ่มเพื่อเปิดปิดอุปกรณ์");
}

void loop() {
  bool now = digitalRead(BUTTON);

  if (lastState == HIGH && now == LOW) {  // จังหวะที่เพิ่งกดลง
    relayOn = !relayOn;
    digitalWrite(RELAY, relayOn ? LOW : HIGH);
    digitalWrite(LED, relayOn);

    if (relayOn) {
      onSince = millis();
      Serial.println("เปิดอุปกรณ์");
      beep(1500, 80);
    } else {
      unsigned long sec = (millis() - onSince) / 1000;
      Serial.print("ปิดอุปกรณ์  เปิดไปทั้งหมด ");
      Serial.print(sec);
      Serial.println(" วินาที");
      beep(800, 80);
    }
    delay(50);                            // กันอาการเด้งของปุ่ม
  }
  lastState = now;

  if (relayOn) {                          // รายงานทุก 1 วินาทีขณะเปิดอยู่
    static unsigned long tick = 0;
    if (millis() - tick > 1000) {
      tick = millis();
      Serial.print("เปิดมาแล้ว ");
      Serial.print((millis() - onSince) / 1000);
      Serial.println(" วินาที");
    }
  }
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

