// เซนเซอร์ที่ 06 : โรตารีเอนโคดเดอร์ (Rotary Encoder)
// ฐานที่ 3  ·  บอร์ด Arduino Uno R3
// การต่อสาย : +/VCC->5V , GND->GND , CLK->D2 , DT->D3 , SW->D4

const int CLK = 2, DT = 3, SW = 4;
int position = 0;
int lastClk;

void setup() {
  pinMode(CLK, INPUT);
  pinMode(DT, INPUT);
  pinMode(SW, INPUT_PULLUP);
  lastClk = digitalRead(CLK);
  Serial.begin(9600);
}

void loop() {
  int clk = digitalRead(CLK);
  if (clk != lastClk) {
    if (digitalRead(DT) != clk) position++;    // หมุนขวา
    else position--;                           // หมุนซ้าย
    Serial.println(position);
  }
  lastClk = clk;

  if (digitalRead(SW) == LOW) {                // กดปุ่ม = เริ่มนับใหม่
    position = 0;
    Serial.println("Reset");
    delay(300);
  }
}

fun.code:
// ============================================================
// ฐาน 3 · เซนเซอร์ 06 · โรตารีเอนโคดเดอร์
// ลูกเล่น : หมุนปรับความสว่างไฟ 0-100% มีเสียงติ๊กทุกขั้น กดปุ่มรีเซ็ต
// ต่อสาย  : CLK->D2, DT->D3, SW->D4, +->5V, GND->GND
//           LED ผ่านตัวต้านทาน 220 โอห์ม -> D9 | บัซเซอร์ +->D8, -->GND
// ============================================================
const int CLK = 2, DT = 3, SW = 4;
const int LED_PWM = 9;               // ต้องเป็นขา PWM (มีเครื่องหมาย ~)
const int BUZZER  = 8;

int level = 50;                      // ความสว่างเริ่มต้น 50%
int lastClk;

void setup() {
  pinMode(CLK, INPUT);
  pinMode(DT, INPUT);
  pinMode(SW, INPUT_PULLUP);
  pinMode(LED_PWM, OUTPUT);
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  lastClk = digitalRead(CLK);
  show();
}

void loop() {
  int clk = digitalRead(CLK);

  if (clk != lastClk) {
    if (digitalRead(DT) != clk) level += 5;   // หมุนขวา สว่างขึ้น
    else                        level -= 5;   // หมุนซ้าย มืดลง
    level = constrain(level, 0, 100);
    show();
    beep(1200, 15);                           // เสียงติ๊กเบา ๆ ทุกขั้น
  }
  lastClk = clk;

  if (digitalRead(SW) == LOW) {               // กดปุ่ม = กลับไป 50%
    level = 50;
    show();
    Serial.println("รีเซ็ตกลับ 50%");
    beep(600, 120);
    delay(300);
  }
}

void show() {
  analogWrite(LED_PWM, map(level, 0, 100, 0, 255));
  Serial.print("ความสว่าง ");
  Serial.print(level);
  Serial.print("%  ");
  for (int i = 0; i < level / 5; i++) Serial.print("#");   // แถบกราฟ
  Serial.println();
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

