// ============================================================
// ฐาน 3 · เซนเซอร์ 06 · โรตารีเอนโคดเดอร์  [ลูกเล่น + LCD]
// LCD โชว์เปอร์เซ็นต์ความสว่างพร้อมแถบกราฟ หมุนปรับ กดปุ่มรีเซ็ต
// ต่อสาย : CLK->D2, DT->D3, SW->D4 | LED+ตัวต้านทาน 220R ->D9
//          บัซเซอร์ +->D8 | LCD SDA->A4, SCL->A5
// ============================================================
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int CLK = 2, DT = 3, SW = 4;
const int LED_PWM = 9;
const int BUZZER  = 8;

int level = 50;
int lastClk;

void setup() {
  pinMode(CLK, INPUT); pinMode(DT, INPUT); pinMode(SW, INPUT_PULLUP);
  pinMode(LED_PWM, OUTPUT); pinMode(BUZZER, OUTPUT);
  lcd.init(); lcd.backlight();
  lastClk = digitalRead(CLK);
  lcd.print("Turn to dim LED");
  delay(1200);
  lcd.clear();
  show();
}

void loop() {
  int clk = digitalRead(CLK);
  if (clk != lastClk) {
    if (digitalRead(DT) != clk) level += 5;    // หมุนขวา
    else                        level -= 5;    // หมุนซ้าย
    level = constrain(level, 0, 100);
    show();
    tone(BUZZER, 1200, 12);
  }
  lastClk = clk;

  if (digitalRead(SW) == LOW) {                // กดปุ่มรีเซ็ต
    level = 50;
    show();
    tone(BUZZER, 600, 120);
    delay(300);
  }
}

void show() {
  analogWrite(LED_PWM, map(level, 0, 100, 0, 255));
  lcd.setCursor(0, 0);
  lcd.print("Brightness ");
  lcd.print(level);
  lcd.print("%   ");

  lcd.setCursor(0, 1);
  int bars = map(level, 0, 100, 0, 16);
  for (int i = 0; i < 16; i++) lcd.print(i < bars ? (char)255 : ' ');
}

