// ต่อสาย  : เซนเซอร์ DO->D2, VCC->5V, GND->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int PIN_IR = 2;
const int BUZZER = 8;
const int LED    = 13;

int  count = 0;
bool onLine = false;

void setup() {
  pinMode(PIN_IR, INPUT);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  delay(500);
  onLine = (digitalRead(PIN_IR) == HIGH);    // จำสภาพเริ่มต้น กันนับผิดตอนเปิดเครื่อง
