}

void loop() {
  bool black = (digitalRead(PIN_IR) == HIGH);   // HIGH = ไม่สะท้อน = เส้นดำ

  if (black && !onLine) {                       // เพิ่งเข้าเส้นดำ นับ 1
    count++;
    Serial.print("เส้นที่ ");
    Serial.println(count);
    digitalWrite(LED, HIGH);
    beep(1800, 60);
    digitalWrite(LED, LOW);
  }
  onLine = black;

  if (count >= 10) {                            // ครบ 10 เส้น ฉลอง
    Serial.println("ครบ 10 เส้นแล้ว! เริ่มนับใหม่");
    beep(1000,120); beep(1400,120); beep(2000,220);
    count = 0;
    delay(500);
  }
  delay(20);
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
