// ============================================================
// ฐาน 4 · เซนเซอร์ 08 · เซนเซอร์สนามแม่เหล็ก
// ลูกเล่น : เครื่องวัดรอบ ติดแม่เหล็กบนล้อแล้วหมุน คำนวณ RPM ให้
// ต่อสาย  : เซนเซอร์ S->D2, +->5V, -->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int PIN_HALL = 2;
const int BUZZER   = 8;
const int LED      = 13;

int  turns = 0;
bool near  = false;
unsigned long lastReport = 0;

void setup() {
  pinMode(PIN_HALL, INPUT);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("เอาแม่เหล็กผ่านหน้าเซนเซอร์ซ้ำ ๆ แล้วดูรอบต่อนาที");
}

void loop() {
  bool found = (digitalRead(PIN_HALL) == LOW);   // LOW = เจอแม่เหล็ก

  if (found && !near) {                          // เพิ่งผ่านมา นับ 1 รอบ
    turns++;
    digitalWrite(LED, HIGH);
    beep(2200, 30);
    digitalWrite(LED, LOW);
  }
  near = found;

  if (millis() - lastReport >= 3000) {           // สรุปทุก 3 วินาที
    int rpm = turns * 20;                        // 3 วินาที x 20 = 1 นาที
    Serial.print("นับได้ ");
    Serial.print(turns);
    Serial.print(" รอบ ใน 3 วินาที  =  ");
    Serial.print(rpm);
    Serial.println(" รอบต่อนาที");
    turns = 0;
    lastReport = millis();
  }
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

