// ============================================================
// ฐาน 4 · เซนเซอร์ 08 · เซนเซอร์สนามแม่เหล็ก  [ลูกเล่น + LCD]
// สองอย่างในตัวเดียว : ทดสอบขั้วแม่เหล็ก N/S + เครื่องวัดรอบ
// ชิปในเซนเซอร์ตอบสนองขั้วเดียวเท่านั้น เอาอีกขั้วมาจะไม่ติดเลย
// ต่อสาย : เซนเซอร์ S->D2 | บัซเซอร์ +->D8 | LCD SDA->A4, SCL->A5
// ============================================================
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int PIN_HALL = 2;
const int BUZZER   = 8;

int  turns = 0;
int  totalHits = 0;
bool near = false;
unsigned long lastReport = 0;

void setup() {
  pinMode(PIN_HALL, INPUT);
  pinMode(BUZZER, OUTPUT);
  lcd.init();
  lcd.backlight();

  lcd.print("Magnet Tester");
  lcd.setCursor(0, 1);
  lcd.print("Try both poles!");
  delay(2500);
  lcd.clear();
  lcd.print("Waiting magnet");
}

void loop() {
  bool found = (digitalRead(PIN_HALL) == LOW);   // LOW = เจอขั้วที่ถูก

  if (found && !near) {                          // เพิ่งผ่านเข้ามา
    turns++;
    totalHits++;
    tone(BUZZER, 2200, 30);
    lcd.setCursor(0, 0);
    lcd.print("FOUND! pole OK  ");
  }
  if (!found && near) {
    lcd.setCursor(0, 0);
    lcd.print("No magnet       ");
  }
  near = found;

  if (millis() - lastReport >= 3000) {           // สรุปรอบทุก 3 วินาที
    lcd.setCursor(0, 1);
    if (totalHits == 0) {
      lcd.print("Flip magnet? ");                // ยังไม่เคยติดเลย แนะให้กลับขั้ว
      lcd.print("   ");
    } else {
      int rpm = turns * 20;                      // 3 วินาที x 20 = 1 นาที
      lcd.print("RPM ");
      lcd.print(rpm);
      lcd.print("        ");
    }
    turns = 0;
    lastReport = millis();
  }
}

