// ============================================================
// ฐาน 5 · เซนเซอร์ 10 · เซนเซอร์วัดระยะอัลตราโซนิก
// ลูกเล่น : เซนเซอร์ถอยรถ ยิ่งเข้าใกล้ยิ่งบี๊บถี่ ใกล้มากดังยาว
// ต่อสาย  : TRIG->D9, ECHO->D10, VCC->5V, GND->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int TRIG = 9, ECHO = 10;
const int BUZZER = 8;
const int LED    = 13;

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("เลื่อนมือเข้าออกหน้าเซนเซอร์");
}

void loop() {
  float cm = readDistance();

  if (cm <= 0) {                       // วัดไม่ได้ ข้ามรอบนี้
    Serial.println("วัดไม่ได้");
    delay(200);
    return;
  }

  Serial.print(cm, 0);
  Serial.print(" ซม.  ");

  if (cm > 50) {                       // ไกล ปลอดภัย ไม่ต้องเตือน
    Serial.println("ปลอดภัย");
    digitalWrite(LED, LOW);
    delay(200);
  } else if (cm > 10) {                // ใกล้ขึ้น บี๊บถี่ขึ้นเรื่อย ๆ
    Serial.println("ระวัง");
    digitalWrite(LED, HIGH);
    beep(1500, 60);
    digitalWrite(LED, LOW);
    delay(map((long)cm, 10, 50, 40, 500));   // ยิ่งใกล้ ยิ่งหน่วงสั้น
  } else {                             // ใกล้มาก ดังยาว
    Serial.println(">> ใกล้มาก หยุด! <<");
    digitalWrite(LED, HIGH);
    beep(2500, 400);
    digitalWrite(LED, LOW);
    delay(60);
  }
}

float readDistance() {
  digitalWrite(TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long t = pulseIn(ECHO, HIGH, 30000);       // รอไม่เกิน 30 มิลลิวินาที
  if (t == 0) return -1;
  return t * 0.0343 / 2;
}

void beep(int freq, int ms) {          // บัซเซอร์ passive ใช้ tone()
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

