  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); pinMode(BUZZER, OUTPUT);
  lcd.init(); lcd.backlight();
  lcd.print("Parking Sensor");
  delay(1500);
  lcd.clear();
}

