  float cm = readDistance();

  lcd.setCursor(0, 0);
  if (cm <= 0) {
    lcd.print("Out of range    ");
    lcd.setCursor(0, 1); lcd.print("                ");
    delay(250);
    return;
  }

  lcd.print("Dist ");
