    tone(BUZZER, 1500, 60);
    delay(map((long)cm, 10, 50, 60, 500));       // ใกล้ = บี๊บถี่
  } else {
    lcd.print(">>>  STOP!  <<<<");
    tone(BUZZER, 2500, 400);
    delay(450);
  }
