fun.code:
// ============================================================
// ฐาน 7 · เซนเซอร์ 14 · เซนเซอร์เสียงกำลังสูง
// ลูกเล่น : มาตรวัดเสียงในห้อง วาดแถบกราฟ ดังเกินกำหนดจะเตือน
// ต่อสาย  : เซนเซอร์ AO->A0, +->5V, -->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int PIN_A  = A0;
const int BUZZER = 8;
const int LED    = 13;

int quiet = 0;              // ค่าตอนห้องเงียบ วัดเองตอนเริ่ม
int limit = 0;              // เกินเท่านี้ถือว่าดังเกินไป

void setup() {
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);

  Serial.println("เงียบ ๆ 3 วินาที กำลังวัดระดับพื้นฐานของห้อง...");
  long sum = 0;
  for (int i = 0; i < 60; i++) { sum += peak(); delay(50); }
  quiet = sum / 60;
  limit = quiet + 150;
  Serial.print("ห้องเงียบอยู่ที่ "); Serial.print(quiet);
  Serial.print("  จะเตือนเมื่อเกิน "); Serial.println(limit);
}

void loop() {
  int level = peak();
  int bars  = map(level, quiet, quiet + 300, 0, 20);
  bars = constrain(bars, 0, 20);

  Serial.print(level);
  Serial.print("  ");
  for (int i = 0; i < bars; i++) Serial.print("|");     // แถบกราฟเสียง

  if (level > limit) {
    Serial.println("   << ดังเกินไป!");
    digitalWrite(LED, HIGH);
    beep(2500, 150);
    digitalWrite(LED, LOW);
  } else {
    Serial.println();
  }
  delay(150);
}

int peak() {                             // หาค่าสูงสุดใน 50 มิลลิวินาที
  int p = 0;
  unsigned long start = millis();
  while (millis() - start < 50) {
    int v = analogRead(PIN_A);
    if (v > p) p = v;
  }
  return p;
}

void beep(int freq, int ms) {
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

