// ต่อสาย : เซนเซอร์ AO->A0 | บัซเซอร์ +->D8 | LCD SDA->A4, SCL->A5
// ============================================================
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int PIN_A  = A0;
const int BUZZER = 8;

int  closedValue = 0;
bool doorOpen = false;
int  opens = 0;

void setup() {
