// ฐานที่ 8  ·  บอร์ด Arduino Uno R3
// การต่อสาย : +/VCC->5V , -/GND->GND , S/OUT->D2

const int PIN_TAP = 2;
int knocks = 0;

void setup() {
  pinMode(PIN_TAP, INPUT);
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(PIN_TAP) == LOW) {     // เคาะ 1 ครั้ง
    knocks++;
    Serial.print("เคาะครั้งที่ ");
    Serial.println(knocks);
    delay(250);
  }

