fun.code:
// ============================================================
// ฐาน 8 · เซนเซอร์ 16 · เซนเซอร์ตรวจการเคาะ
// ลูกเล่น : ล็อกรหัสเคาะ เคาะ 3 ครั้งใน 3 วินาทีจึงปลดล็อก ช้าไปต้องเริ่มใหม่
// ต่อสาย  : เซนเซอร์ S->D2, +->5V, -->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int PIN_TAP = 2;
const int BUZZER  = 8;
const int LED     = 13;

const int CODE_LENGTH = 3;          // ต้องเคาะกี่ครั้งจึงปลดล็อก
int  knocks = 0;
bool lastState;
unsigned long firstKnock = 0;

void setup() {
  pinMode(PIN_TAP, INPUT_PULLUP);   // กันขาลอย ไม่ให้นับผีหลอก
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  delay(1000);                      // รอให้นิ่งก่อนจำสถานะเริ่มต้น
  lastState = digitalRead(PIN_TAP);
  Serial.println("เคาะ 3 ครั้งใน 3 วินาทีเพื่อปลดล็อก");
}

void loop() {
  bool now = digitalRead(PIN_TAP);

  if (now != lastState) {           // ตรวจเฉพาะจังหวะที่สถานะเปลี่ยน
    if (knocks == 0) firstKnock = millis();
    knocks++;
    Serial.print("เคาะครั้งที่ ");
    Serial.println(knocks);
    beep(1600, 50);
    delay(250);                     // หน่วงกันนับซ้ำจากการสั่นค้าง
    lastState = digitalRead(PIN_TAP);

    if (knocks >= CODE_LENGTH) {
      unlock();
      knocks = 0;
    }
    return;
  }
  lastState = now;

  if (knocks > 0 && millis() - firstKnock > 3000) {   // ช้าเกินไป
    Serial.println("ช้าเกินไป เริ่มใหม่");
    beep(400, 300);
    knocks = 0;
  }
}

void unlock() {
  Serial.println(">>> ปลดล็อกสำเร็จ! <<<");
  digitalWrite(LED, HIGH);
  beep(1046, 120);   // โด
  beep(1318, 120);   // มี
  beep(1568, 120);   // ซอล
  beep(2093, 300);   // โดสูง
  delay(1500);
  digitalWrite(LED, LOW);
  Serial.println("ล็อกอีกครั้ง เคาะใหม่ได้เลย");
}

void beep(int freq, int ms) {
  tone(BUZZER, freq);
  delay(ms);
  noTone(BUZZER);
}

