fun.code:
// ============================================================
// ฐาน 9 · เซนเซอร์ 18 · โมดูลปุ่มกด
// ลูกเล่น : เกมวัดปฏิกิริยา พอได้ยินเสียงให้กดปุ่มให้เร็วที่สุด วัดเป็นมิลลิวินาที
// ต่อสาย  : ปุ่มกด ขาหนึ่ง->D2 อีกขา->GND | บัซเซอร์ +->D8, -->GND
// ============================================================
const int BUTTON = 2;
const int BUZZER = 8;
const int LED    = 13;

unsigned long best = 999999;         // สถิติดีที่สุด
int round_ = 0;

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  Serial.println("=== เกมวัดปฏิกิริยา ===");
  Serial.println("พอไฟติดและมีเสียง ให้กดปุ่มให้เร็วที่สุด");
  Serial.println("กดปุ่มเพื่อเริ่ม");
  while (digitalRead(BUTTON) == HIGH) { }     // รอกดเริ่ม
  delay(300);
}

void loop() {
  round_++;
  Serial.print("\nรอบที่ ");
  Serial.print(round_);
  Serial.println("  เตรียมตัว...");

  int wait = random(2000, 5000);              // สุ่มเวลารอ กันเดา
  unsigned long start = millis();
  while (millis() - start < (unsigned long)wait) {
    if (digitalRead(BUTTON) == LOW) {         // กดก่อนสัญญาณ = ฟาวล์
      Serial.println("กดเร็วเกินไป! รอสัญญาณก่อน");
      tone(BUZZER, 300, 500); delay(600);
      waitRelease();
      return;
    }
  }

  digitalWrite(LED, HIGH);                    // สัญญาณ!
  tone(BUZZER, 2000);
  unsigned long signalAt = millis();

  while (digitalRead(BUTTON) == HIGH) { }     // รอจนกด
  unsigned long ms = millis() - signalAt;     // ต้องเป็น unsigned long ไม่ใช่ int

  noTone(BUZZER);
  digitalWrite(LED, LOW);

  Serial.print("เวลาปฏิกิริยา ");
  Serial.print(ms);
  Serial.println(" มิลลิวินาที");

  if (ms < best) {
    best = ms;
    Serial.println(">>> สถิติใหม่! <<<");
    tone(BUZZER, 1046, 100); delay(120);
    tone(BUZZER, 1568, 100); delay(120);
    tone(BUZZER, 2093, 250); delay(300);
  }
  Serial.print("สถิติดีที่สุด ");
  Serial.print(best);
  Serial.println(" มิลลิวินาที");

  waitRelease();
  Serial.println("กดปุ่มอีกครั้งเพื่อเล่นรอบต่อไป");
  while (digitalRead(BUTTON) == HIGH) { }
  waitRelease();
}

void waitRelease() {                          // รอจนปล่อยปุ่ม กันอ่านซ้ำ
  while (digitalRead(BUTTON) == LOW) { }
  delay(50);
}

lcd.code:
// ============================================================
// ฐาน 9 · เซนเซอร์ 18 · ปุ่มกด  [ลูกเล่น + LCD]
// เกมวัดปฏิกิริยา LCD โชว์เวลาและสถิติ ไม่ต้องเปิด Serial Monitor
// ต่อสาย : ปุ่มกด ขาหนึ่ง->D2 อีกขา->GND | บัซเซอร์ +->D8 | LCD SDA->A4, SCL->A5
// ============================================================
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

const int BUTTON = 2;
const int BUZZER = 8;

unsigned long best = 999999;
int round_ = 0;

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  lcd.init(); lcd.backlight();
  randomSeed(analogRead(A0));

  lcd.print("Reaction Game");
  lcd.setCursor(0, 1);
  lcd.print("Press to start");
  while (digitalRead(BUTTON) == HIGH) { }
  waitRelease();
}

void loop() {
  round_++;
  lcd.clear();
  lcd.print("Round ");
  lcd.print(round_);
  lcd.setCursor(0, 1);
  lcd.print("Get ready...");

  unsigned long wait = random(2000, 5000);        // สุ่มเวลารอ กันเดา
  unsigned long start = millis();
  while (millis() - start < wait) {
    if (digitalRead(BUTTON) == LOW) {             // กดก่อนสัญญาณ = ฟาวล์
      lcd.clear();
      lcd.print("TOO EARLY!");
      lcd.setCursor(0, 1);
      lcd.print("Wait for beep");
      tone(BUZZER, 300, 500);
      delay(1500);
      waitRelease();
      return;
    }
  }

  lcd.clear();
  lcd.print("*** NOW! ***");
  tone(BUZZER, 2000);
  unsigned long signalAt = millis();

  while (digitalRead(BUTTON) == HIGH) { }
  unsigned long ms = millis() - signalAt;
  noTone(BUZZER);

  lcd.clear();
  lcd.print("Time ");
  lcd.print(ms);
  lcd.print(" ms");

  lcd.setCursor(0, 1);
  if (ms < best) {
    best = ms;
    lcd.print("NEW RECORD!");
    tone(BUZZER, 1046, 100); delay(120);
    tone(BUZZER, 1568, 100); delay(120);
    tone(BUZZER, 2093, 250); delay(300);
  } else {
    lcd.print("Best ");
    lcd.print(best);
    lcd.print(" ms");
  }

  waitRelease();
  delay(1200);
  while (digitalRead(BUTTON) == HIGH) { }         // รอกดเล่นรอบต่อไป
  waitRelease();
}

void waitRelease() {
  while (digitalRead(BUTTON) == LOW) { }
  delay(50);
}
